const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs');
const app=fs.readFileSync('app.js','utf8'),css=fs.readFileSync('styles.css','utf8');
test('5.8.0 activa Hablar como vista completa y oculta la ficha',()=>{assert.match(app,/thokar-ios26-prototype-1/);const tail=css.slice(css.indexOf('5.7.1 — Hablar'));assert.match(tail,/workspace-top\{display:none!important\}/);assert.match(tail,/workspace-scroll[\s\S]*position:fixed!important/)});
test('5.8.0 reserva fila visible para compositor',()=>{const tail=css.slice(css.indexOf('5.7.1 — Hablar'));assert.match(tail,/grid-template-rows:auto minmax\(0,1fr\) auto!important/);assert.match(tail,/composer-wrap[\s\S]*display:block!important/);assert.match(tail,/composer[\s\S]*min-height:66px!important/)});
test('5.8.0 usa visualViewport y con teclado reduce chat, no compositor',()=>{const fn=app.slice(app.indexOf('function fitTalkWindow'),app.indexOf('function navIndex'));assert.match(fn,/syncViewport\(\)/);const tail=css.slice(css.indexOf('5.7.1 — Hablar'));assert.match(tail,/keyboard-open[\s\S]*workspace-main\.view-talk/);assert.match(tail,/keyboard-open \.liquid-tabbar\{display:none!important\}/)});
